import sys
import math

def build_segment_tree(arr, n, tree, node, start, end):
    if start == end:
        tree[node] = arr[start]
    else:
        mid = (start + end) // 2
        build_segment_tree(arr, n, tree, 2 * node, start, mid)
        build_segment_tree(arr, n, tree, 2 * node + 1, mid + 1, end)
        tree[node] = math.gcd(tree[2 * node], tree[2 * node + 1])

def update_segment_tree(arr, n, tree, node, start, end, idx, val):
    if start == end:
        arr[idx] = val
        tree[node] = val
    else:
        mid = (start + end) // 2
        if idx <= mid:
            update_segment_tree(arr, n, tree, 2 * node, start, mid, idx, val)
        else:
            update_segment_tree(arr, n, tree, 2 * node + 1, mid + 1, end, idx, val)
        tree[node] = math.gcd(tree[2 * node], tree[2 * node + 1])

def query_segment_tree(tree, node, start, end, l, r):
    if r < start or end < l:
        return 0
    if l <= start and end <= r:
        return tree[node]
    mid = (start + end) // 2
    left_gcd = query_segment_tree(tree, 2 * node, start, mid, l, r)
    right_gcd = query_segment_tree(tree, 2 * node + 1, mid + 1, end, l, r)
    return math.gcd(left_gcd, right_gcd)

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    idx = 0
    n = int(data[idx]); idx += 1
    q = int(data[idx]); idx += 1

    arr = []
    for _ in range(n):
        arr.append(int(data[idx]))
        idx += 1

    # Build segment tree with 4*n size
    tree = [0] * (4 * n)
    if n > 0:
        build_segment_tree(arr, n, tree, 1, 0, n - 1)

    output = []
    for _ in range(q):
        if idx >= len(data):
            break
        typ = int(data[idx]); idx += 1
        if typ == 1:
            idx_val = int(data[idx]); idx += 1
            val = int(data[idx]); idx += 1
            if n > 0:
                update_segment_tree(arr, n, tree, 1, 0, n - 1, idx_val, val)
        elif typ == 2:
            l = int(data[idx]); idx += 1
            r = int(data[idx]); idx += 1
            if n == 0:
                output.append("0")
            else:
                result = query_segment_tree(tree, 1, 0, n - 1, l, r)
                output.append(str(result))

    sys.stdout.write("\n".join(output))
    if output:
        sys.stdout.write("\n")

if __name__ == "__main__":
    main()
